import {
  type AtRule,
  type Container,
  type Document,
  type PluginCreator,
  Rule,
} from 'postcss'
import selectorParser from 'postcss-selector-parser'
import { warn } from '../warn'
import { SelectorRewriteState } from './cssVars'

const animationNameRE = /^(-\w+-)?animation-name$/
const animationRE = /^(-\w+-)?animation$/

const scopedPlugin: PluginCreator<string> = (id = '') => {
  const keyframes = Object.create(null)
  const shortId = id.replace(/^data-v-/, '')
  const rewriter = new ScopedSelectorRewriter(id)

  return {
    postcssPlugin: 'vue-sfc-scoped',
    Rule(rule) {
      rewriter.processRule(rule)
    },
    AtRule(node) {
      if (
        /-?keyframes$/.test(node.name) &&
        !node.params.endsWith(`-${shortId}`)
      ) {
        // register keyframes
        keyframes[node.params] = node.params = node.params + '-' + shortId
      }
    },
    OnceExit(root) {
      if (Object.keys(keyframes).length) {
        // If keyframes are found in this <style>, find and rewrite animation names
        // in declarations.
        // Caveat: this only works for keyframes and animation rules in the same
        // <style> element.
        // individual animation-name declaration
        root.walkDecls(decl => {
          if (animationNameRE.test(decl.prop)) {
            decl.value = decl.value
              .split(',')
              .map(v => keyframes[v.trim()] || v.trim())
              .join(',')
          }
          // shorthand
          if (animationRE.test(decl.prop)) {
            decl.value = decl.value
              .split(',')
              .map(v => {
                const vals = v.trim().split(/\s+/)
                const i = vals.findIndex(val => keyframes[val])
                if (i !== -1) {
                  vals.splice(i, 1, keyframes[vals[i]])
                  return vals.join(' ')
                } else {
                  return v
                }
              })
              .join(',')
          }
        })
      }
    },
  }
}

const processedRules = new WeakSet<Rule>()

class ScopedSelectorRewriter {
  private readonly scopeId: string
  private readonly slottedSuffix = '-s'

  constructor(scopeId: string) {
    this.scopeId = scopeId
  }

  processRule(rule: Rule) {
    if (
      processedRules.has(rule) ||
      (rule.parent &&
        rule.parent.type === 'atrule' &&
        /-?keyframes$/.test((rule.parent as AtRule).name))
    ) {
      return
    }
    processedRules.add(rule)
    let deep = false
    let parent: Document | Container | undefined = rule.parent
    while (parent && parent.type !== 'root') {
      if ((parent as any).__deep) {
        deep = true
        break
      }
      parent = parent.parent
    }
    rule.selector = selectorParser(selectorRoot => {
      selectorRoot.each(selector => {
        this.rewriteSelector(
          new SelectorRewriteState(selector, selectorRoot, deep, false, rule),
        )
      })
    }).processSync(rule.selector)
  }

  rewriteSelector(state: SelectorRewriteState) {
    let node: selectorParser.Node | null = null
    let shouldInject = !state.isDeep
    // find the last child node to insert attribute selector
    state.selector.each(n => {
      // DEPRECATED ">>>" and "/deep/" combinator
      if (
        n.type === 'combinator' &&
        (n.value === '>>>' || n.value === '/deep/')
      ) {
        n.value = ' '
        n.spaces.before = n.spaces.after = ''
        warn(
          `the >>> and /deep/ combinators have been deprecated. ` +
            `Use :deep() instead.`,
        )
        return false
      }

      if (n.type === 'pseudo') {
        const { value } = n
        // deep: inject [id] attribute at the node before the ::v-deep
        // combinator.
        if (value === ':deep' || value === '::v-deep') {
          state.nested.markDeep()
          if (n.nodes.length) {
            // .foo ::v-deep(.bar) -> .foo[xxxxxxx] .bar
            // replace the current node with ::v-deep's inner selector
            let last: selectorParser.Selector['nodes'][0] = n
            n.nodes[0].each(ss => {
              state.selector.insertAfter(last, ss)
              last = ss
            })
            // insert a space combinator before if it doesn't already have one
            const prev = state.selector.at(state.selector.index(n) - 1)
            if (!prev || !isSpaceCombinator(prev)) {
              state.selector.insertAfter(
                n,
                selectorParser.combinator({
                  value: ' ',
                }),
              )
            }
            state.selector.removeChild(n)
          } else {
            // DEPRECATED usage
            // .foo ::v-deep .bar -> .foo[xxxxxxx] .bar
            warn(
              `${value} usage as a combinator has been deprecated. ` +
                `Use :deep(<inner-selector>) instead of ${value} <inner-selector>.`,
            )

            const prev = state.selector.at(state.selector.index(n) - 1)
            if (prev && isSpaceCombinator(prev)) {
              state.selector.removeChild(prev)
            }
            state.selector.removeChild(n)
          }
          return false
        }

        // slot: use selector inside `::v-slotted` and inject [id + '-s']
        // instead.
        // ::v-slotted(.foo) -> .foo[xxxxxxx-s]
        if (value === ':slotted' || value === '::v-slotted') {
          this.rewriteSelector(state.createChild(n.nodes[0], true))
          let last: selectorParser.Selector['nodes'][0] = n
          n.nodes[0].each(ss => {
            state.selector.insertAfter(last, ss)
            last = ss
          })
          // selector.insertAfter(n, n.nodes[0])
          state.selector.removeChild(n)
          // since slotted attribute already scopes the selector there's no
          // need for the non-slot attribute.
          shouldInject = false
          return false
        }

        // global: replace with inner selector and do not inject [id].
        // ::v-global(.foo) -> .foo
        if (value === ':global' || value === '::v-global') {
          state.selectorRoot.insertAfter(state.selector, n.nodes[0])
          state.selectorRoot.removeChild(state.selector)
          return false
        }
      }

      if (n.type === 'universal') {
        const prev = state.selector.at(state.selector.index(n) - 1)
        const next = state.selector.at(state.selector.index(n) + 1)
        // * ... {}
        if (!prev) {
          // * .foo {} -> .foo[xxxxxxx] {}
          if (next) {
            if (next.type === 'combinator' && next.value === ' ') {
              state.selector.removeChild(next)
            }
            state.selector.removeChild(n)
            return
          } else {
            // * {} -> [xxxxxxx] {}
            node = selectorParser.combinator({
              value: '',
            })
            state.selector.insertBefore(n, node)
            state.selector.removeChild(n)
            return false
          }
        }
        // .foo * -> .foo[xxxxxxx] *
        if (node) return
      }

      if (
        (n.type !== 'pseudo' && n.type !== 'combinator') ||
        (n.type === 'pseudo' &&
          (n.value === ':is' || n.value === ':where') &&
          !node)
      ) {
        node = n
      }
    })

    if (state.nested.childNodes.some(node => node.type === 'rule')) {
      const deep = state.nested.markedDeep
      const decls = state.nested.childNodes.filter(node => node.type === 'decl')
      if (!deep && decls.length) {
        for (const decl of decls) {
          state.nested.removeChild(decl)
        }
        const hostRule = new Rule({
          nodes: decls,
          selector: '&',
        })
        state.nested.prepend(hostRule)
      }
      shouldInject = deep
    }

    if (node) {
      const { type, value } = node as selectorParser.Node
      if (type === 'pseudo' && (value === ':is' || value === ':where')) {
        ;(node as selectorParser.Pseudo).nodes.forEach(value =>
          this.rewriteSelector(state.createChild(value)),
        )
        shouldInject = false
      }
    }

    if (node) {
      ;(node as selectorParser.Node).spaces.after = ''
    } else {
      // For deep selectors & standalone pseudo selectors,
      // the attribute selectors are prepended rather than appended.
      // So all leading spaces must be eliminated to avoid problems.
      state.selector.first.spaces.before = ''
    }

    if (shouldInject) {
      const idToAdd = state.nested.isSlotted
        ? this.scopeId + this.slottedSuffix
        : this.scopeId
      state.selector.insertAfter(
        // If node is null it means we need to inject [id] at the start
        // insertAfter can handle `null` here
        node as any,
        selectorParser.attribute({
          attribute: idToAdd,
          value: idToAdd,
          raws: {},
          quoteMark: `"`,
        }),
      )
    }
  }
}

function isSpaceCombinator(node: selectorParser.Node) {
  return node.type === 'combinator' && /^\s+$/.test(node.value)
}

scopedPlugin.postcss = true
export default scopedPlugin

import {
  type BindingMetadata,
  NodeTypes,
  type SimpleExpressionNode,
  createRoot,
  createSimpleExpression,
  createTransformContext,
  processExpression,
} from '@vue/compiler-dom'
import type { SFCDescriptor } from '../parse'
import type { PluginCreator, Rule } from 'postcss'
import type { Root, Selector } from 'postcss-selector-parser'
import { NestedRuleSnapshot } from './pluginTrim'
import hash from 'hash-sum'
import { getEscapedCssVarName } from '@vue/shared'

export const CSS_VARS_HELPER = `useCssVars`

export function genCssVarsFromList(
  vars: string[],
  id: string,
  isProd: boolean,
  isSSR = false,
): string {
  return `{\n  ${vars
    .map(
      key =>
        `"${isSSR ? `--` : ``}${genVarName(id, key, isProd, isSSR)}": (${key})`,
    )
    .join(',\n  ')}\n}`
}

function genVarName(
  id: string,
  raw: string,
  isProd: boolean,
  isSSR = false,
): string {
  if (isProd) {
    return hash(id + raw)
  } else {
    // escape ASCII Punctuation & Symbols
    // #7823 need to double-escape in SSR because the attributes are rendered
    // into an HTML string
    return `${id}-${getEscapedCssVarName(raw, isSSR)}`
  }
}

function normalizeExpression(exp: string) {
  exp = exp.trim()
  if (
    (exp[0] === `'` && exp[exp.length - 1] === `'`) ||
    (exp[0] === `"` && exp[exp.length - 1] === `"`)
  ) {
    return exp.slice(1, -1)
  }
  return exp
}

const vBindRE = /v-bind\s*\(/g

export function parseCssVars(sfc: SFCDescriptor): string[] {
  const vars: string[] = []
  sfc.styles.forEach(style => {
    let match
    // ignore v-bind() in comments, eg /* ... */
    // and // (Less, Sass and Stylus all support the use of // to comment)
    const content = style.content.replace(/\/\*([\s\S]*?)\*\/|\/\/.*/g, '')
    while ((match = vBindRE.exec(content))) {
      const start = match.index + match[0].length
      const end = lexBinding(content, start)
      if (end !== null) {
        const variable = normalizeExpression(content.slice(start, end))
        if (!vars.includes(variable)) {
          vars.push(variable)
        }
      }
    }
  })
  return vars
}

enum LexerState {
  inParens,
  inSingleQuoteString,
  inDoubleQuoteString,
}

function lexBinding(content: string, start: number): number | null {
  let state: LexerState = LexerState.inParens
  let parenDepth = 0

  for (let i = start; i < content.length; i++) {
    const char = content.charAt(i)
    switch (state) {
      case LexerState.inParens:
        if (char === `'`) {
          state = LexerState.inSingleQuoteString
        } else if (char === `"`) {
          state = LexerState.inDoubleQuoteString
        } else if (char === `(`) {
          parenDepth++
        } else if (char === `)`) {
          if (parenDepth > 0) {
            parenDepth--
          } else {
            return i
          }
        }
        break
      case LexerState.inSingleQuoteString:
        if (char === `'`) {
          state = LexerState.inParens
        }
        break
      case LexerState.inDoubleQuoteString:
        if (char === `"`) {
          state = LexerState.inParens
        }
        break
    }
  }
  return null
}

// for compileStyle
export interface CssVarsPluginOptions {
  id: string
  isProd: boolean
}

export const cssVarsPlugin: PluginCreator<CssVarsPluginOptions> = opts => {
  const { id, isProd } = opts!
  return {
    postcssPlugin: 'vue-sfc-vars',
    Declaration(decl) {
      // rewrite CSS variables
      const value = decl.value
      if (vBindRE.test(value)) {
        vBindRE.lastIndex = 0
        let transformed = ''
        let lastIndex = 0
        let match
        while ((match = vBindRE.exec(value))) {
          const start = match.index + match[0].length
          const end = lexBinding(value, start)
          if (end !== null) {
            const variable = normalizeExpression(value.slice(start, end))
            transformed +=
              value.slice(lastIndex, match.index) +
              `var(--${genVarName(id, variable, isProd)})`
            lastIndex = end + 1
          }
        }
        decl.value = transformed + value.slice(lastIndex)
      }
    },
  }
}
cssVarsPlugin.postcss = true

export function genCssVarsCode(
  vars: string[],
  bindings: BindingMetadata,
  id: string,
  isProd: boolean,
) {
  const varsExp = genCssVarsFromList(vars, id, isProd)
  const exp = createSimpleExpression(varsExp, false)
  const context = createTransformContext(createRoot([]), {
    prefixIdentifiers: true,
    inline: true,
    bindingMetadata: bindings.__isScriptSetup === false ? undefined : bindings,
  })
  const transformed = processExpression(exp, context)
  const transformedString =
    transformed.type === NodeTypes.SIMPLE_EXPRESSION
      ? transformed.content
      : transformed.children
          .map(c => {
            return typeof c === 'string'
              ? c
              : (c as SimpleExpressionNode).content
          })
          .join('')

  return `_${CSS_VARS_HELPER}(_ctx => (${transformedString}))`
}

// <script setup> already gets the calls injected as part of the transform
// this is only for single normal <script>
export function genNormalScriptCssVarsCode(
  cssVars: string[],
  bindings: BindingMetadata,
  id: string,
  isProd: boolean,
  defaultVar: string,
): string {
  return (
    `\nimport { ${CSS_VARS_HELPER} as _${CSS_VARS_HELPER} } from 'vue'\n` +
    `const __injectCSSVars__ = () => {\n${genCssVarsCode(
      cssVars,
      bindings,
      id,
      isProd,
    )}}\n` +
    `const __setup__ = ${defaultVar}.setup\n` +
    `${defaultVar}.setup = __setup__\n` +
    `  ? (props, ctx) => { __injectCSSVars__();return __setup__(props, ctx) }\n` +
    `  : __injectCSSVars__\n`
  )
}

export class SelectorRewriteState {
  selector: Selector
  selectorRoot: Root
  isDeep: boolean
  nested: NestedRuleSnapshot

  constructor(
    selector: Selector,
    selectorRoot: Root,
    isDeep: boolean,
    isSlotted: boolean,
    hostRule: Rule,
  ) {
    this.selector = selector
    this.selectorRoot = selectorRoot
    this.isDeep = isDeep
    this.nested = new NestedRuleSnapshot(hostRule, isSlotted)
  }

  createChild(selector: Selector, slotted = this.nested.isSlotted) {
    return new SelectorRewriteState(
      selector,
      this.selectorRoot,
      this.isDeep,
      slotted,
      this.nested.getHostRule(),
    )
  }
}

